    # TCP/IP
    q("cai-net-tcp", "easy", "Dans quel ordre se fait le handshake TCP ?", "SYN, SYN-ACK, ACK", "SYN, ACK, SYN-ACK", "ACK, SYN, SYN-ACK", "SYN-ACK, SYN, ACK", "Trois segments pour ouvrir. La fermeture utilise FIN et ACK dans chaque sens."),
